const { ethers } = require("ethers");
require("dotenv").config();
const { decideChains } = require("../../../config/provider");

const SIMULATOR_BYTECODE =
  "";

const ROUTERS = {
  1: "0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D", // uniswapV2
  56: "0x10ED43C718714eb63d5aA57B78B54704E256024E", // PancakeSwap v2
  8453: "0x327Df1E6de05895d2ab08513aaDD9313Fe505d86", // BaseSwap
  42161: "0x1b02dA8Cb0d097eB8D57A175b88c7D8b47997506", // SushiSwap
};

const SIMULATOR_ABI = [
  "function simulateTrade(address token, address router) external payable returns (tuple(uint256 buyTax, uint256 sellTax, bool isHoneypot, string reason))",
];
const iface = new ethers.Interface(SIMULATOR_ABI);

const _runHoneypotCheck = async (targetContract, chainId = 1) => {
  try {
    const { provider } = decideChains(chainId);
    const dexRouterAddress = ROUTERS[chainId];

    if (!dexRouterAddress)
      throw new Error("Unsupported DEX Router for this chain");

    const callData = iface.encodeFunctionData("simulateTrade", [
      targetContract,
      dexRouterAddress,
    ]);

    // We use Vitalik's address as the EOA
    const VITALIK_SENDER = "0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045";

    // THE NIGHTMARE FIX: We inject the simulator bytecode directly into Vitalik's address.
    // This makes tx.origin == msg.sender true, bypassing smart contract honeypot filters.
    const stateOverride = {
      [VITALIK_SENDER]: {
        code: SIMULATOR_BYTECODE,
        balance: ethers.toBeHex(ethers.parseEther("1")), // Give him 1 ETH for the swap
      },
    };

    const intervals = [
      { label: "Immediate", delay: 0 },
      { label: "24 Hours", delay: 86400 },
      { label: "7 Days", delay: 604800 },
    ];

    let finalResult = {
      riskScore: 0,
      buyTax: 0,
      sellTax: 0,
      isTimeHoneypot: false,
      errorReason: "",
      timeTravelResults: [],
    };

    const now = Math.floor(Date.now() / 1000);

    for (const interval of intervals) {
      const futureTimestamp = now + interval.delay;

      const txObj = {
        from: VITALIK_SENDER,
        to: VITALIK_SENDER, // We call the injected code ON the EOA itself
        data: callData,
        value: ethers.toBeHex(ethers.parseEther("0.1")), // Swap 0.1 native token
        gas: "0x1C9C380",
      };

      const params = [txObj, "latest", stateOverride];

      if (interval.delay > 0) {
        params.push({ timestamp: ethers.toBeHex(futureTimestamp) });
      }

      try {
        const response = await provider.send("eth_call", params);

        if (!response || response === "0x") {
          throw new Error("Simulation reverted without data.");
        }

        const decoded = iface.decodeFunctionResult(
          "simulateTrade",
          response,
        )[0];

        const isHoneypot = decoded[2];
        const currentRisk = isHoneypot
          ? 100
          : Math.max(Number(decoded[0]), Number(decoded[1]));

        const result = {
          label: interval.label,
          buyTax: Number(decoded[0]),
          sellTax: Number(decoded[1]),
          riskScore: currentRisk,
          errorReason: decoded[3],
        };

        finalResult.timeTravelResults.push(result);

        if (interval.delay === 0) {
          finalResult.buyTax = result.buyTax;
          finalResult.sellTax = result.sellTax;
          finalResult.riskScore = result.riskScore;
          finalResult.errorReason = result.errorReason;
        } else {
          // If a later time check suddenly spikes the tax or reverts, it's a time-lock honeypot
          if (
            result.riskScore > finalResult.riskScore ||
            result.buyTax > finalResult.buyTax + 10
          ) {
            finalResult.isTimeHoneypot = true;
            finalResult.riskScore = 100;
            finalResult.errorReason = `Time-Delayed Trap: ${result.errorReason}`;
          }
        }
      } catch (err) {
        console.warn(
          `[TxShield] Time Travel (${interval.label}) Failed:`,
          err.message,
        );

        if (interval.delay === 0) {
          finalResult.riskScore = 100;
          finalResult.errorReason = `Fatal Revert: Dead token or unverified assembly trap. (${err.message})`;
          break; // Save compute units on dead tokens
        }
      }
    }

    return finalResult;
  } catch (err) {
    console.error(`Honeypot Fatal Error: ${err.message}`);
    throw err;
  }
};

module.exports = _runHoneypotCheck;
